insert into overload.biblioteca (id, nome, nome_pt, musculo, acessorios, equipamento, pilha_kg, instrucoes_pt) values
  ('hack', 'Hack squat', 'Hack squat', 'QUADRÍCEPS', array['GLÚTEOS']::text[], 'carregada', null, array['Costas e ombros apoiados, pés no meio da plataforma na largura do quadril.', 'Desça controlando até a coxa passar da paralela, sem tirar o quadril do encosto.', 'Suba empurrando com o pé inteiro, sem travar o joelho no topo.']::text[]),
  ('leg45', 'Leg press 45°', 'Leg press 45°', 'QUADRÍCEPS', '{}', 'carregada', null, array['Pés no meio da plataforma e lombar colada no banco.', 'Desça até o joelho chegar perto do peito sem a lombar sair do apoio.', 'Empurre de volta sem estender o joelho por completo.']::text[]),
  ('ext', 'Cadeira extensora', 'Cadeira extensora', 'QUADRÍCEPS', '{}', 'pilha', 100, array['Ajuste o encosto para o joelho ficar alinhado ao eixo da máquina.', 'Estenda as pernas até quase travar e segure um instante no topo.', 'Volte devagar até o peso quase encostar na pilha.']::text[]),
  ('extr', 'Extensora tronco reclinado', 'Extensora tronco reclinado', 'QUADRÍCEPS', '{}', 'pilha', 100, array['Encosto reclinado para o quadríceps trabalhar alongado, joelho alinhado ao eixo.', 'Estenda as pernas até quase travar, sem tirar o quadril do banco.', 'Volte devagar até o peso quase encostar na pilha.']::text[]),
  ('stiff', 'Stiff', 'Stiff', 'POSTERIOR', array['GLÚTEOS']::text[], 'barra', null, array['Barra rente às pernas, joelhos levemente flexionados e fixos.', 'Leve o quadril para trás e desça a barra junto à coxa até sentir o posterior alongar.', 'Suba contraindo os glúteos, com a coluna neutra o tempo todo.']::text[]),
  ('flex', 'Cadeira flexora', 'Cadeira flexora', 'POSTERIOR', '{}', 'pilha', 100, array['Joelho alinhado ao eixo da máquina e rolo logo acima do calcanhar.', 'Flexione até o rolo chegar perto do glúteo, sem levantar o quadril.', 'Volte controlando até quase estender.']::text[]),
  ('flexpe', 'Flexão de pernas em pé', 'Flexão de pernas em pé', 'POSTERIOR', '{}', 'pilha', 70, array['Quadril apoiado no encosto e rolo acima do calcanhar.', 'Flexione uma perna de cada vez, sem girar o quadril.', 'Volte devagar até quase estender.']::text[]),
  ('adut', 'Cadeira adutora', 'Cadeira adutora', 'ADUTORES', '{}', 'pilha', 100, array['Costas no encosto e abertura no limite confortável.', 'Feche as pernas contraindo a parte interna da coxa.', 'Abra devagar até sentir o alongamento.']::text[]),
  ('pants', 'Panturrilha sentado', 'Panturrilha sentado', 'PANTURRILHA', '{}', 'carregada', null, array['Joelhos sob a almofada e ponta dos pés na plataforma.', 'Desça o calcanhar o máximo possível e pause embaixo.', 'Suba até a ponta dos pés e segure um instante.']::text[]),
  ('pantp', 'Panturrilha em pé na máquina', 'Panturrilha em pé na máquina', 'PANTURRILHA', '{}', 'pilha', 100, array['Ombros sob as almofadas e ponta dos pés na plataforma.', 'Desça o calcanhar até alongar e pause embaixo.', 'Suba até a ponta dos pés sem dobrar os joelhos.']::text[]),
  ('pux', 'Puxada alta aberta', 'Puxada alta aberta', 'COSTAS', array['BÍCEPS']::text[], 'pilha', 100, array['Pegada aberta, coxas presas sob o apoio.', 'Puxe a barra até o alto do peito levando os cotovelos para baixo e para trás.', 'Volte até os braços quase estenderem, sem soltar os ombros.']::text[]),
  ('puxf', 'Puxada alta fechada', 'Puxada alta fechada', 'COSTAS', array['BÍCEPS']::text[], 'pilha', 100, array['Pegada fechada no triângulo e peito alto.', 'Puxe até o peito com os cotovelos rentes ao corpo.', 'Volte controlando até alongar as costas.']::text[]),
  ('tbar', 'T-bar row aberta', 'T-bar row aberta', 'COSTAS', array['OMBROS']::text[], 'carregada', null, array['Peito no apoio, pegada aberta.', 'Puxe levando os cotovelos para fora e para trás.', 'Desça até os braços estenderem, sem arredondar a lombar.']::text[]),
  ('pullo', 'Pullover com corda', 'Pullover com corda', 'COSTAS', '{}', 'pilha', 70, array['De frente para a polia alta, corda nas mãos e braços quase estendidos.', 'Leve a corda até a coxa num arco, sem dobrar os cotovelos.', 'Volte até sentir as costas alongarem acima da cabeça.']::text[]),
  ('dev', 'Desenvolvimento no Smith', 'Desenvolvimento no Smith', 'OMBROS', array['PEITO']::text[], 'smith', null, array['Banco a 80 ou 90 graus, barra na altura do queixo.', 'Empurre até quase estender os cotovelos, sem arquear a lombar.', 'Desça controlando até a altura do queixo.']::text[]),
  ('elev', 'Elevação lateral na máquina', 'Elevação lateral na máquina', 'OMBROS', '{}', 'pilha', 70, array['Braços nas almofadas, cotovelos levemente flexionados.', 'Eleve até a linha dos ombros sem subir o trapézio.', 'Desça devagar, sem deixar o peso encostar.']::text[]),
  ('crucr', 'Crucifixo reverso na máquina', 'Crucifixo reverso na máquina', 'OMBROS', '{}', 'pilha', 70, array['Peito no apoio e pegadas na altura dos ombros.', 'Abra os braços para trás contraindo o deltoide posterior.', 'Volte devagar sem deixar o peso encostar.']::text[]),
  ('sup', 'Supino inclinado no Smith', 'Supino inclinado no Smith', 'PEITO', array['TRÍCEPS']::text[], 'smith', null, array['Banco a 30 graus, barra na linha do alto do peito.', 'Desça até tocar de leve o peito, com os cotovelos a cerca de 45 graus.', 'Empurre de volta sem travar os cotovelos.']::text[]),
  ('supH', 'Supino inclinado com halteres', 'Supino inclinado com halteres', 'PEITO', array['TRÍCEPS']::text[], 'halteres', null, array['Banco a 30 graus, halteres na linha do peito.', 'Desça até alongar o peito, com os cotovelos a cerca de 45 graus.', 'Empurre de volta aproximando os halteres no topo.']::text[]),
  ('pecfly', 'Pec fly na máquina', 'Pec fly na máquina', 'PEITO', '{}', 'pilha', 100, array['Banco ajustado para as pegadas ficarem na linha do peito.', 'Feche os braços contraindo o peito, com os cotovelos levemente flexionados.', 'Abra devagar até alongar.']::text[]),
  ('paral', 'Tríceps paralela na máquina', 'Tríceps paralela na máquina', 'TRÍCEPS', array['OMBROS']::text[], 'pilha', 100, array['Tronco levemente inclinado à frente e cotovelos junto ao corpo.', 'Empurre até estender os cotovelos.', 'Volte até o cotovelo passar de 90 graus.']::text[]),
  ('pul', 'Tríceps pulley', 'Tríceps pulley', 'TRÍCEPS', '{}', 'pilha', 70, array['Cotovelos colados ao corpo, barra ou corda na altura do peito.', 'Estenda os cotovelos até o fim sem mover os ombros.', 'Volte devagar até cerca de 90 graus.']::text[]),
  ('scott', 'Rosca Scott na máquina', 'Rosca Scott na máquina', 'BÍCEPS', '{}', 'pilha', 70, array['Axila encostada no apoio e braços estendidos.', 'Flexione até o antebraço passar da vertical.', 'Desça devagar até quase estender.']::text[])
